  "mes.group.ngRepair.tip": { "zh-CN": "统一管理确认NG、送修、收单、维修、复活和复测", "vi-VN": "Quản lý xác nhận NG, chuyển, nhận, sửa, khôi phục và kiểm tra lại", "en-US": "Manage confirmed NG, transfer, receipt, repair, revival, and retest" },
