  "mes.contribution.reason.productCore": { "zh-CN": "直接决定产品身份、位置、路线或履历，属于产品主线核心。", "vi-VN": "Quyết định trực tiếp danh tính, vị trí, tuyến hoặc lịch sử sản phẩm.", "en-US": "Directly determines product identity, location, route, or history." },
  "mes.contribution.reason.ngClosure": { "zh-CN": "直接推动NG从确认到维修、复测和结案，属于NG闭环核心。", "vi-VN": "Trực tiếp đưa NG từ xác nhận đến sửa chữa, kiểm tra lại và đóng.", "en-US": "Directly advances NG from confirmation through repair, retest, and closure." },
  "mes.contribution.reason.ngPrevention": { "zh-CN": "在缺陷发生或流出前识别风险，同时保护产品状态和NG质量。", "vi-VN": "Nhận diện rủi ro trước khi lỗi xảy ra hoặc lọt ra ngoài.", "en-US": "Identifies risk before a defect occurs or escapes." },
  "mes.contribution.reason.material": { "zh-CN": "保证产品使用正确物料并形成消耗证据，对产品贡献为主。", "vi-VN": "Đảm bảo sản phẩm dùng đúng vật liệu và có bằng chứng tiêu hao.", "en-US": "Ensures correct material use and creates consumption evidence." },
  "mes.contribution.reason.projection": { "zh-CN": "提供可视化和现场定位，但不直接决定产品或NG状态。", "vi-VN": "Cung cấp hiển thị và định vị nhưng không quyết định trạng thái.", "en-US": "Provides visualization and location without deciding product or NG state." },
  "mes.contribution.reason.governance": { "zh-CN": "提供产品与NG共同使用的规则、主数据和治理能力。", "vi-VN": "Cung cấp quy tắc, dữ liệu chủ và quản trị dùng chung.", "en-US": "Provides shared rules, master data, and governance for product and NG." },
