  "mes.smtLoading.loadingTitle": { "zh-CN": "执行SMT物料上料", "vi-VN": "Thực hiện nạp vật liệu SMT", "en-US": "Execute SMT material loading" },
  "mes.smtLoading.loadingHint": { "zh-CN": "进入后按MES计划扫描机器、通道、飞达和物料；验证通过后才能绑定。", "vi-VN": "Quét máy, kênh, feeder và vật liệu theo kế hoạch MES; chỉ được liên kết sau khi xác nhận đạt.", "en-US": "Scan machine, channel, feeder, and material per MES plan; binding is allowed only after validation." },
  "mes.smtLoading.unlockTitle": { "zh-CN": "机器/通道/飞达/物料解锁", "vi-VN": "Mở khóa máy/kênh/feeder/vật liệu", "en-US": "Machine/channel/feeder/material unlock" },
  "mes.smtLoading.unlockHint": { "zh-CN": "MES规则必须同时匹配工单、机器、通道、飞达和物料批次。", "vi-VN": "Quy tắc MES phải khớp đồng thời WO, máy, kênh, feeder và lô vật liệu.", "en-US": "MES rules must match the WO, machine, channel, feeder, and material lot together." },
  "mes.smtLoading.unlockRule": { "zh-CN": "PDA不能本地解锁；IQC/QMS或时间窗不通过时保持阻断。", "vi-VN": "PDA không được mở khóa cục bộ; vẫn chặn khi IQC/QMS hoặc khung thời gian không đạt.", "en-US": "The PDA cannot unlock locally; loading stays blocked when IQC/QMS or timing gates fail." },
