  "mes.smtLoading.loadFailed": { "zh-CN": "SMT计划加载失败", "vi-VN": "Không tải được kế hoạch SMT", "en-US": "Could not load SMT plan" },
  "mes.smtExemption.title": { "zh-CN": "SMT物料例外审批", "vi-VN": "Phê duyệt ngoại lệ vật liệu SMT", "en-US": "SMT Material Exemptions" },
  "mes.smtExemption.subtitle": { "zh-CN": "线长提交，厂长授权；所有例外受MES规则和审计控制。", "vi-VN": "Trưởng chuyền yêu cầu, quản lý nhà máy phê duyệt; mọi ngoại lệ được MES kiểm soát và ghi audit.", "en-US": "Line Manager requests; Plant Manager authorizes. Every exception is governed and audited by MES." },
  "mes.smtExemption.warning": { "zh-CN": "例外不会绕过IQC、QMS或MES门禁；IQC_BLOCKED和EXPIRY_BLOCKED必须由质量流程处理。", "vi-VN": "Ngoại lệ không bỏ qua cổng IQC, QMS hoặc MES; IQC_BLOCKED và EXPIRY_BLOCKED phải qua quy trình chất lượng.", "en-US": "An exemption cannot bypass IQC, QMS, or MES gates. IQC_BLOCKED and EXPIRY_BLOCKED require quality disposition." },
  "mes.smtExemption.requestTitle": { "zh-CN": "线长例外申请", "vi-VN": "Yêu cầu ngoại lệ của trưởng chuyền", "en-US": "Line Manager Request" },
