  // ── AI Patrol (shared) ────────────────────────────────────────────────
  "patrol.welcome": { "zh-CN": "🤖 我是 AI 巡检助手。选择模块后我可以分析数据异常、预警风险、给出建议。点击「加载数据」开始。", "vi-VN": "🤖 Tôi là trợ lý AI tuần tra. Chọn module và tôi sẽ phân tích bất thường, cảnh báo rủi ro và đưa ra gợi ý. Nhấn「Tải dữ liệu」để bắt đầu.", "en-US": "🤖 I'm the AI patrol assistant. Select a module and I can analyze data anomalies, alert risks, and give recommendations. Click「Load Data」to start." },
