  "patrol.wms.subtitle": { "zh-CN": "库存异常、有效期、FIFO 违规、IQC 积压预警", "vi-VN": "Bất thường tồn kho, HSD, vi phạm FIFO, cảnh báo IQC tồn đọng", "en-US": "Inventory anomalies, expiry alerts, FIFO violations, IQC backlog warnings" },
