  "patrol.quality.subtitle": { "zh-CN": "IQC 合格率、不良趋势、客户投诉、巡检异常", "vi-VN": "Tỷ lệ IQC đạt, xu hướng lỗi, khiếu nại KH, bất thường tuần tra", "en-US": "IQC pass rate, defect trends, customer complaints, patrol anomalies" },
